assignments.value:
={{ (() => {
  if ($('Contexto nuevo').isExecuted) { return ''; }
  let resumen = '';
  try {
    const r = JSON.parse($json.last_summary);
    resumen = 'Asunto: ' + r.asunto_principal + '. Puntos clave: ' + (r.puntos_clave || []).join('; ') + '. Accion requerida: ' + r.accion_requerida;
  } catch (e) { resumen = $json.last_summary || ''; }
  const partes = [];
  if ($json.user_name) { partes.push('El usuario se llama ' + $json.user_name + '.'); }
  if (resumen) { partes.push('El contexto de vuestra última charla es: ' + resumen + '.'); }
  if ($json.status) { partes.push('Estado de su última solicitud: ' + $json.status + '.'); }
  return '[INICIO DE CONTEXTO COMPARTIDO]\nCONFIGURACIÓN DE IDENTIDAD Y MEMORIA DE LARGO PLAZO\n' + partes.join('\n') + '\n[FIN DEL CONTEXTO COMPARTIDO]';
})() }}
